// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    Bank bank;

    function setUp() public {
        c = new ModifierEntrancy();
        bank = new Bank();
    }

    function testFuzz_property(uint256 seed) public {
        // Any seed is admissible; the caller must be a contract whose
        // supportsToken() matches, so route the call through a fresh Bank,
        // which by construction has tokenBalance == 0 (never airdropped).
        vm.prank(address(bank));
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a fresh account with zero balance and a valid token
        // signature always receives the airdrop (balance becomes 20).
        assertTrue(ok && c.tokenBalance(address(bank)) == 20);
    }
}
